const inside = ([x0, y0, z0, x1, y1, z1], x, y, z) => x >= x0 && x <= x1 && y >= y0 && y <= y1 && z >= z0 && z <= z1;

/** Writer for one footprint: put(x, y, z, block, state, over) writes only inside box, never at y0, and only into air
 *  unless over is true. */
function writer(g, box) {
