const stateKey = (s = {}) => JSON.stringify(Object.entries(s).map(([k, v]) => [k, String(v)]).sort());
const inside = ([x0, y0, z0, x1, y1, z1], x, y, z) => x >= x0 && x <= x1 && y >= y0 && y <= y1 && z >= z0 && z <= z1;

